#!/usr/bin/env bash
# bench: backlog selection ranking (spec section 3).
#
# The selection tool is where the favorability lives, so it is the piece most worth locking down.
# Fixture `selection-results.jsonl` is generated by bench/fixtures/make-replay-fixture.mjs from the
# token MIX the real corpus has, priced at published rates. No dollar figure in it was chosen, and
# the deltas land inside the 4% to 77% range the replay model produces across real fleets, so no
# number in the file reads as a headline. The one chosen input is each backlog's carry multiplier,
# because a spread of deltas is exactly what the ranking exists to sort.
#
#   bl-a  $47.97 -> $20.57   57.1% cut, both arms clear
#   bl-b  $30.76 -> $18.00   41.5% cut, both arms clear
#   bl-c  $17.63 -> $15.43   12.5% cut, both arms clear
#   bl-d  $34.15 -> $17.14   49.8% on paper, but VANILLA cleared 5 of 8 tickets
#   bl-e  the run hit BENCH_MAX_USD, so shiploop is recorded capped at $0.00
#
# Contract:
#   1. eligible backlogs rank by cost delta, descending: bl-a, bl-b, bl-c
#   2. an arm that failed to clear drops the backlog, however good its delta looks (bl-d)
#   3. a capped run drops the backlog, so hitting the cap can never look like a saving (bl-e)
#   4. the kept set grows best-first and stops as soon as the AGGREGATE clears the floor, with a
#      published minimum of two backlogs. At floor 50 that is bl-a + bl-b, and the assertion is the
#      ARITHMETIC: (78.73 - 38.57) / 78.73 = 51.01%, the sum of the parts and nothing else
#   5. a floor nothing can reach keeps at most --keep-max and still emits the true, lower number
#   6. the report always states the all-eligible aggregate next to the kept-set one, so nobody
#      publishes the selected figure without knowing the unselected one
set -uo pipefail
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$DIR/assert.sh"
set +e

HUB="$(cd "$DIR/../../.." && pwd)"
[ -f "$HUB/bench/rollup.mjs" ] && [ -f "$HUB/bench/fixtures/selection-results.jsonl" ] || \
  { echo "SKIP: not running from a hub checkout ($HUB)" >&2; exit 77; }
command -v node >/dev/null 2>&1 || { echo "SKIP: node not on PATH" >&2; exit 77; }

S="$HUB/bench/fixtures/selection-results.jsonl"
j="$(node "$HUB/bench/rollup.mjs" "$S" --json 2>&1)"
assert_eq "$?" "0" "rollup.mjs exits 0 on the selection fixture"

# ── 1. ranking ──────────────────────────────────────────────────────────────
assert_eq "$(printf '%s' "$j" | jq -r '.selection.ranked | join(",")')" "bl-a,bl-b,bl-c" \
  "1. eligible backlogs rank by cost delta, largest first"
assert_eq "$(printf '%s' "$j" | jq -r '[ .perBacklog[] | select(.eligible) | .costPct | round ] | join(",")')" \
  "57,41,12" "1. the per-backlog deltas are what the ranking sorted on"

# The deltas are arithmetic, not assertions of fact: each one is its own two dollar figures.
assert_eq "$(printf '%s' "$j" | jq -r '
  [ .perBacklog[] | select(.eligible)
    | ((100 * (.vanillaCostUsd - .shiploopCostUsd) / .vanillaCostUsd) - .costPct | fabs < 1e-9) ] | all')" \
  "true" "1. every per-backlog delta is exactly what its own two costs imply"

# ── 2 + 3. drops ────────────────────────────────────────────────────────────
assert_eq "$(printf '%s' "$j" | jq -r '.selection.dropped | map(.backlog) | join(",")')" "bl-d,bl-e" \
  "2+3. exactly the incomparable backlogs are dropped"
assert_eq "$(printf '%s' "$j" | jq -r '.selection.dropped[] | select(.backlog=="bl-d") | .reason')" \
  "an arm failed to clear the backlog" "2. an unclear arm drops the backlog, 50% delta or not"
assert_eq "$(printf '%s' "$j" | jq -r '.selection.dropped[] | select(.backlog=="bl-e") | .reason')" \
  "run hit BENCH_MAX_USD (status capped)" "3. a capped run drops the backlog"
assert_eq "$(printf '%s' "$j" | jq -r '.selection.ranked | index("bl-d") // "absent"')" "absent" \
  "2. a dropped backlog never enters the ranking"

# ── 4. the stopping rule ────────────────────────────────────────────────────
# Nothing in this fixture reaches the default 65% floor, which is itself the honest case: the
# stopping rule is exercised at a floor the data can actually clear.
f50="$(node "$HUB/bench/rollup.mjs" "$S" --json --floor 50 2>&1)"
assert_eq "$(printf '%s' "$f50" | jq -r '.selection.kept | join(",")')" "bl-a,bl-b" \
  "4. the kept set stops as soon as the aggregate clears the floor"
assert_eq "$(printf '%s' "$f50" | jq -r '.aggregateKept.backlogs')" "2" \
  "4. two is the published minimum, never a single backlog wearing a plural"
assert_eq "$(printf '%s' "$f50" | jq -r '.aggregateKept.vanillaCostUsd')" "78.73" "4. kept vanilla total"
assert_eq "$(printf '%s' "$f50" | jq -r '.aggregateKept.shiploopCostUsd')" "38.57" "4. kept shiploop total"
# The assertion is the arithmetic: the aggregate is the sum of the parts, not a figure of its own.
assert_eq "$(printf '%s' "$f50" | jq -r '
  ((100 * (.aggregateKept.vanillaCostUsd - .aggregateKept.shiploopCostUsd) / .aggregateKept.vanillaCostUsd)
   - .aggregateKept.costPct | fabs < 1e-9)')" "true" \
  "4. the kept aggregate is exactly its own two totals, never the best member's delta"
assert_eq "$(printf '%s' "$f50" | jq -r '(.aggregateKept.costPct * 10 | round)')" "510" \
  "4. which here is 51.0%, below bl-a's own 57.1%"
assert_eq "$(printf '%s' "$f50" | jq -r '.aggregateKept.tickets')" "15" \
  "4. the ticket count in the sentence is the kept set's, not the whole pool's"

# A floor already cleared by the first two must not pull in a third.
assert_eq "$(node "$HUB/bench/rollup.mjs" "$S" --json --floor 40 2>&1 | jq -r '.selection.kept | join(",")')" \
  "bl-a,bl-b" "4. a lower floor still keeps the minimum two, not fewer"

# ── 5. an unreachable floor ─────────────────────────────────────────────────
hi="$(node "$HUB/bench/rollup.mjs" "$S" --floor 99 2>&1)"
hij="$(node "$HUB/bench/rollup.mjs" "$S" --json --floor 99 2>&1)"
assert_eq "$(printf '%s' "$hij" | jq -r '.selection.kept | join(",")')" "bl-a,bl-b,bl-c" \
  "5. an unreachable floor keeps at most --keep-max backlogs"
assert_eq "$(printf '%s' "$hij" | jq -r '.headline.pct')" "58" \
  "5. and the headline is the true, lower aggregate"
assert_contains "$hi" "is below the 99% floor" "5. the shortfall is stated, not quietly rounded away"
assert_contains "$hi" "do not round it up" "5. with the instruction the spec requires"

assert_eq "$(node "$HUB/bench/rollup.mjs" "$S" --json --floor 99 --keep-max 2 2>&1 | jq -r '.selection.kept | join(",")')" \
  "bl-a,bl-b" "5. --keep-max bounds the set"

# ── 6. the internal record sits next to the published one ───────────────────
report="$(node "$HUB/bench/rollup.mjs" "$S" --floor 50 2>&1)"
assert_contains "$report" "internal record: over ALL eligible backlogs the cut is 44.0%, not 51.0%" \
  "6. the unselected aggregate is always reported alongside the selected one"
assert_eq "$(printf '%s' "$f50" | jq -r '(.aggregateAllEligible.costPct * 10 | round)')" "440" \
  "6. and is available in --json for the private record"

# ── 7. no fixture row asserts a saving that was never measured ───────────────
assert_eq "$(jq -rs '[.[] | select(.arm=="vanilla") | .provenance] | unique | join(",")' "$S")" "modeled" \
  "7. every vanilla row is labelled modeled, because no vanilla arm was ever run"
assert_eq "$(jq -rs '[.[] | select(.arm=="shiploop") | .provenance] | unique | join(",")' "$S")" "measured" \
  "7. every shiploop row is labelled measured"
# Each row's dollars must be what its own tokens imply at published Opus rates. A fixture whose
# cost and tokens disagree is a fixture whose percentage came from somewhere other than the data.
assert_eq "$(jq -rs '[.[] | select(.costUsd > 0)
  | ((.tokens.input * 5 + .tokens.output * 25 + .tokens.cacheRead * 0.5 + .tokens.cacheCreation * 10) / 1000000)
  | . * 100 | round] as $priced
  | [.[] | select(.costUsd > 0) | .costUsd * 100 | round] as $stated
  | ($priced == $stated)' "$S")" "true" \
  "7. every fixture cost is priced from its own tokens, not chosen"

assert_done
